import importlib.util,pathlib,unittest,subprocess,sys,json,copy
p=pathlib.Path(sys.argv[1]);sys.argv=[sys.argv[0]]
s=importlib.util.spec_from_file_location('deps',p/'deps.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
class Tests(unittest.TestCase):
 def test_order(self): self.assertEqual(m.order({'z':['a'],'a':[],'b':[]}),['a','b','z'])
 def test_dynamic(self): self.assertEqual(m.order({'b':[],'a':['b'],'z':[]}),['b','a','z'])
 def test_missing_duplicate(self): self.assertEqual(m.order({'c':['b','b'],'b':['a']}),['a','b','c'])
 def test_empty(self): self.assertEqual(m.order({}),[])
 def test_no_mutation(self):
  g={'c':['b','b'],'b':['a']};orig=copy.deepcopy(g);m.order(g);self.assertEqual(g,orig)
 def test_cycle(self):
  for g in [{'a':['a']},{'a':['b'],'b':['a']},{'ok':[],'a':['b'],'b':['a']}]:
   with self.assertRaisesRegex(ValueError,'cycle'):m.order(g)
 def test_invalid(self):
  for g in [{1:[]},{'a':'b'},{'a':[2]},[]]:
   with self.assertRaises(ValueError):m.order(g)
 def test_cli(self):
  r=subprocess.run([sys.executable,str(p/'deps.py')],input='{"z":["a"]}',capture_output=True,text=True);self.assertEqual(r.returncode,0);self.assertEqual(json.loads(r.stdout),['a','z'])
 def test_cli_errors(self):
  for text in ['bad','{"a":["a"]}','[]']:
   r=subprocess.run([sys.executable,str(p/'deps.py')],input=text,capture_output=True,text=True);self.assertEqual(r.returncode,2);self.assertEqual(r.stdout,'');self.assertTrue(r.stderr)
 def test_docs_tests(self):self.assertTrue((p/'README.md').exists());self.assertTrue(any(p.glob('test*.py')))
unittest.main()
